  it('reduces values', () => {
    const v = Range(0, 10, 2);
    const r = v.reduce<number>((a, b) => a + b, 0);
    expect(r).toEqual(20);
  });

  it('takes and skips values', () => {
    const v = Range(0, 100, 3);
    const r = v.skip(2).take(2);
    expect(r.toArray()).toEqual([6, 9]);
  });

  it('can describe lazy operations', () => {
    expect(
      Range(1, Infinity)
        .map(n => -n)
        .take(5)
        .toArray()
    ).toEqual([-1, -2, -3, -4, -5]);
  });

  it('efficiently chains array methods', () => {
    const v = Range(1, Infinity);
    const r = v
      .filter(x => x % 2 === 0)
      .skip(2)
      .map<number>(x => x * x)
      .take(3)
      .reduce<number>((a, b) => a + b, 0);

    expect(r).toEqual(200);
  });

  it('sliced sequence works even on filtered sequence', () => {
    expect(Range(0, 3).slice(-2).toArray()).toEqual([1, 2]);

    expect(
      Range(0, 3)
        .filter($ => true)
        .slice(-2)
        .toArray()
    ).toEqual([1, 2]);
  });
});
